SELECT /* knowledge_periodic_scan */ 
FROM knowledge_artifact_generation
WHERE status = 'VECTOR_CLEANED' ORDER BY update_time, generation_id LIMIT #{limit}

SELECT 
FROM knowledge_artifact_generation WHERE index_version_id = #{indexVersionId}
ORDER BY generation_id

SELECT d.document_id AS documentId, d.document_version_id AS documentVersionId,
       d.generation_id AS generationId
FROM knowledge_index_document d

WHERE d.index_version_id = #{indexVersionId}
  AND k.status = #{knowledgeStatus} AND k.del_flag = #{delFlag}
  AND i.status = #{indexStatus} AND doc.status = #{documentStatus}
  AND v.parse_status = #{versionStatus} AND g.status = #{generationStatus}
ORDER BY d.document_id, d.id
LIMIT #{offset}, #{limit}

SELECT d.document_id AS documentId, d.document_version_id AS documentVersionId,
       d.generation_id AS generationId,
       v.document_processing_snapshot AS documentProcessingSnapshot
FROM knowledge_index_document d

WHERE d.index_version_id = #{indexVersionId}
  AND k.status = #{knowledgeStatus} AND k.del_flag = #{delFlag}
  AND i.status = #{indexStatus} AND doc.status = #{documentStatus}
  AND v.parse_status = #{versionStatus} AND g.status = #{generationStatus}
ORDER BY d.document_id, d.id

SELECT d.document_id AS documentId, d.document_version_id AS documentVersionId,
       d.generation_id AS generationId
FROM knowledge_index_document d

WHERE d.index_version_id = #{indexVersionId}
  AND k.status = #{knowledgeStatus} AND k.del_flag = #{delFlag}
  AND i.status = #{indexStatus} AND doc.status = #{documentStatus}
  AND v.parse_status = #{versionStatus} AND g.status = #{generationStatus}
